/**
 * @file codegen_conversion.c
 * @brief Emit typed conversions requiring more than one target instruction.
 */

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement. You can change IR if it improves the results/makes things more clear. Also try to split long files (300+) into smaller thematic ones, like optimizer was before"
// Changes: Group this implementation by responsibility.
#include "codegen_internal.h"

void cg_print_conversion(Ctx* ctx,
                         FILE* out,
                         const CgPlacement* placement,
                         IrFunction* fn,
                         IrInstruction* inst) {
  switch (inst->operands.call.type) {
    case IR_FX_TO_STR: {
      IrType type = cg_operand_type(fn, &inst->operands.call.args[0]);
      if (inst->result == IR_INVALID_ID)
        break;
      if (type == IR_INT) {
        fputs("INT2STR ", out);
        cg_print_value(out, placement, inst->result);
        cg_print_ws(out);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        cg_print_nl(out);
      } else if (type == IR_DOUBLE) {
        fputs("FLOAT2STR ", out);
        cg_print_value(out, placement, inst->result);
        cg_print_ws(out);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        cg_print_nl(out);
      } else if (type == IR_STRING) {
        fputs("MOVE ", out);
        cg_print_value(out, placement, inst->result);
        cg_print_ws(out);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        cg_print_nl(out);
      } else if (inst->operands.call.args[0].type == IR_OP_BOOL) {
        fputs("MOVE ", out);
        cg_print_value(out, placement, inst->result);
        fputs(inst->operands.call.args[0].value.bool_value ? " string@true"
                                                           : " string@false",
              out);
        cg_print_nl(out);
      } else if (type == IR_UNIT) {
        fputs("MOVE ", out);
        cg_print_value(out, placement, inst->result);
        fputs(" string@()", out);
        cg_print_nl(out);
      } else if (type == IR_BOOL) {
        fprintf(out, "JUMPIFEQ $cg_tostr_btrue_%zu ",
                ctx->cg_state.builtin_label_id);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        fputs(" bool@true\nMOVE ", out);
        cg_print_value(out, placement, inst->result);
        fprintf(out, " string@false\nJUMP $cg_tostr_end_%zu\n",
                ctx->cg_state.builtin_label_id);
        fprintf(out, "LABEL $cg_tostr_btrue_%zu\nMOVE ",
                ctx->cg_state.builtin_label_id);
        cg_print_value(out, placement, inst->result);
        fprintf(out, " string@true\nLABEL $cg_tostr_end_%zu\n",
                ctx->cg_state.builtin_label_id);
      } else {
        fputs("TYPE GF@$tmp1 ", out);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        cg_print_nl(out);
        // int -> INT2STR
        fprintf(out, "JUMPIFNEQ $cg_tostr_flt_%zu GF@$tmp1 string@int\n",
                ctx->cg_state.builtin_label_id);
        fputs("INT2STR ", out);
        cg_print_value(out, placement, inst->result);
        cg_print_ws(out);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        cg_print_nl(out);
        fprintf(out, "JUMP $cg_tostr_end_%zu\n",
                ctx->cg_state.builtin_label_id);
        // float -> FLOAT2STR
        fprintf(out, "LABEL $cg_tostr_flt_%zu\n",
                ctx->cg_state.builtin_label_id);
        fprintf(out, "JUMPIFNEQ $cg_tostr_str_%zu GF@$tmp1 string@float\n",
                ctx->cg_state.builtin_label_id);
        fputs("FLOAT2STR ", out);
        cg_print_value(out, placement, inst->result);
        cg_print_ws(out);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        cg_print_nl(out);
        fprintf(out, "JUMP $cg_tostr_end_%zu\n",
                ctx->cg_state.builtin_label_id);
        // string -> MOVE
        fprintf(out, "LABEL $cg_tostr_str_%zu\n",
                ctx->cg_state.builtin_label_id);
        fprintf(out, "JUMPIFNEQ $cg_tostr_bool_%zu GF@$tmp1 string@string\n",
                ctx->cg_state.builtin_label_id);
        fputs("MOVE ", out);
        cg_print_value(out, placement, inst->result);
        cg_print_ws(out);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        cg_print_nl(out);
        fprintf(out, "JUMP $cg_tostr_end_%zu\n",
                ctx->cg_state.builtin_label_id);
        // bool -> "true" / "false"
        fprintf(out, "LABEL $cg_tostr_bool_%zu\n",
                ctx->cg_state.builtin_label_id);
        fprintf(out, "JUMPIFNEQ $cg_tostr_nil_%zu GF@$tmp1 string@bool\n",
                ctx->cg_state.builtin_label_id);
        fprintf(out, "JUMPIFEQ $cg_tostr_btrue_%zu ",
                ctx->cg_state.builtin_label_id);
        cg_print_operand(out, placement, &inst->operands.call.args[0]);
        fputs(" bool@true", out);
        cg_print_nl(out);
        fputs("MOVE ", out);
        cg_print_value(out, placement, inst->result);
        fputs(" string@false", out);
        cg_print_nl(out);
        fprintf(out, "JUMP $cg_tostr_end_%zu\n",
                ctx->cg_state.builtin_label_id);
        fprintf(out, "LABEL $cg_tostr_btrue_%zu\n",
                ctx->cg_state.builtin_label_id);
        fputs("MOVE ", out);
        cg_print_value(out, placement, inst->result);
        fputs(" string@true", out);
        cg_print_nl(out);
        fprintf(out, "JUMP $cg_tostr_end_%zu\n",
                ctx->cg_state.builtin_label_id);
        // nil (Unit) -> "()"
        fprintf(out, "LABEL $cg_tostr_nil_%zu\n",
                ctx->cg_state.builtin_label_id);
        fputs("MOVE ", out);
        cg_print_value(out, placement, inst->result);
        fputs(" string@()", out);
        cg_print_nl(out);
        fprintf(out, "LABEL $cg_tostr_end_%zu\n",
                ctx->cg_state.builtin_label_id);
      }
      break;
    }
    default:
      break;
  }
}
